from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent; OUT=ROOT/'assets'; OUT.mkdir(exist_ok=True)
D=['#22d3ee','#8b5cf6','#f472b6','#c3f53c']; L=['#0891b2','#7c3aed','#db2777','#65a30d']
def stops(c,d='8s'):
 v=';'.join(c+c[:1]); return ''.join(f'<stop offset="{o}" stop-color="{c[i]}"><animate attributeName="stop-color" values="{v}" dur="{d}" repeatCount="indefinite"/></stop>' for i,o in enumerate(('0%','50%','100%')))
def S(w,h,b): return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{b}</svg>'
def hero(c,dark):
 ink='#f8fafc' if dark else '#0f172a'; muted='#94a3b8' if dark else '#64748b'; grid='#fff' if dark else '#0f172a'
 b=[f'<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="0">{stops(c,"9s")}</linearGradient><linearGradient id="sw"><stop stop-color="#fff" stop-opacity="0"/><stop offset="50%" stop-color="#fff" stop-opacity=".5"/><stop offset="100%" stop-color="#fff" stop-opacity="0"/></linearGradient><mask id="m"><text x="600" y="125" text-anchor="middle" font-family="Segoe UI,Arial" font-size="76" font-weight="700" letter-spacing="5" fill="#fff">LAVANYA MADAN</text></mask></defs>']
 for i in range(9): b.append(f'<line x1="0" y1="{170+i*i*1.6:.0f}" x2="1200" y2="{170+i*i*1.6:.0f}" stroke="{grid}" stroke-opacity=".06"/>')
 for i in range(-8,9): b.append(f'<line x1="{600+i*55}" y1="170" x2="{600+i*175}" y2="300" stroke="{grid}" stroke-opacity=".06"/>')
 for i in range(22):
  x=40+(i*137)%1120; y=30+(i*43)%125; b.append(f'<circle cx="{x}" cy="{y}" r="{1+(i%3)*.5}" fill="{c[i%4]}"><animate attributeName="opacity" values=".05;.6;.05" dur="{4+i%5}s" repeatCount="indefinite"/></circle>')
 b += [f'<text x="600" y="125" text-anchor="middle" font-family="Segoe UI,Arial" font-size="76" font-weight="700" letter-spacing="5" fill="url(#g)">LAVANYA MADAN</text>', '<g mask="url(#m)"><rect x="-400" y="45" width="300" height="100" fill="url(#sw)"><animate attributeName="x" values="-400;1200" dur="5.5s" repeatCount="indefinite"/></rect></g>', f'<text x="600" y="158" text-anchor="middle" font-family="monospace" font-size="14" letter-spacing="6" fill="{muted}">AGENTIC AI · RAG · LLM SYSTEMS · AI PRODUCTS</text>']
 return S(1200,300,''.join(b))
def rule(c): return S(1200,10,f'<defs><linearGradient id="g">{stops(c)}</linearGradient></defs><rect width="1200" y="4" height="2" rx="1" fill="url(#g)" opacity=".3"/><rect x="-150" y="3" width="150" height="3" rx="1.5" fill="{c[0]}"><animate attributeName="x" values="-150;1200" dur="6s" repeatCount="indefinite"/></rect>')
def pipeline(c):
 xs=[100+i*200 for i in range(6)]; names=['INGEST','RETRIEVE','REASON','ACT','EVALUATE','SERVE']; b=[f'<defs><linearGradient id="g">{stops(c)}</linearGradient></defs><rect x="100" y="78" width="1000" height="3" fill="url(#g)" opacity=".35"/>']
 for i,(x,n) in enumerate(zip(xs,names)): b += [f'<circle cx="{x}" cy="80" r="10" fill="none" stroke="{c[i%4]}" stroke-width="2"><animate attributeName="r" values="9;14;9" dur="2.4s" begin="{i*.2}s" repeatCount="indefinite"/></circle>',f'<text x="{x}" y="125" text-anchor="middle" font-family="monospace" font-size="13" letter-spacing="2" fill="#94a3b8">{n}</text>']
 b.append(f'<circle cx="100" cy="80" r="4" fill="{c[0]}"><animate attributeName="cx" values="100;1100;100" dur="5.5s" repeatCount="indefinite"/></circle>'); return S(1200,160,''.join(b))
def card(title,sub,c,dark,kind):
 ink='#f8fafc' if dark else '#0f172a'; shapes={'agent':f'<polygon points="180,105 240,70 300,105 240,140" fill="none" stroke="{c[0]}" stroke-width="4"/><circle cx="240" cy="105" r="9" fill="{c[2]}">','rag':f'<rect x="175" y="65" width="130" height="80" rx="10" fill="none" stroke="{c[1]}" stroke-width="4"/><path d="M190 90h100M190 112h75M190 134h90" stroke="{c[0]}" stroke-width="4"/>','graph':f'<circle cx="205" cy="105" r="16" fill="none" stroke="{c[0]}" stroke-width="4"/><circle cx="280" cy="75" r="16" fill="none" stroke="{c[1]}" stroke-width="4"/><circle cx="285" cy="135" r="16" fill="none" stroke="{c[2]}" stroke-width="4"/><path d="M220 98L264 82M220 112L270 130M282 91L285 119" stroke="{c[3]}" stroke-width="4"/>','eval':f'<path d="M180 130L215 95L245 112L280 72L315 100" fill="none" stroke="{c[0]}" stroke-width="6"><animate attributeName="stroke-dashoffset" values="0;80;0" dur="3s" repeatCount="indefinite"/></path>','memory':f'<ellipse cx="240" cy="72" rx="70" ry="18" fill="none" stroke="{c[0]}" stroke-width="4"/><path d="M170 72v70c0 10 140 10 140 0V72M170 107c0 10 140 10 140 0" fill="none" stroke="{c[1]}" stroke-width="4"/>','tool':f'<path d="M180 135L300 75M205 62l95 95" stroke="{c[0]}" stroke-width="18" stroke-linecap="round"/><circle cx="240" cy="105" r="48" fill="none" stroke="{c[2]}" stroke-width="3" stroke-dasharray="6 8">'}[kind]
 b=f'<g>{shapes}</g><text x="240" y="180" text-anchor="middle" font-family="Segoe UI,Arial" font-size="22" font-weight="700" fill="{ink}">{title}</text><text x="240" y="204" text-anchor="middle" font-family="monospace" font-size="12" letter-spacing="2" fill="#94a3b8">{sub}</text>'; return S(480,220,b)
for dark,c in [(True,D),(False,L)]:
 suf='dark' if dark else 'light'; (OUT/f'hero-{suf}.svg').write_text(hero(c,dark)); (OUT/f'rule-{suf}.svg').write_text(rule(c)); (OUT/f'pipeline-{suf}.svg').write_text(pipeline(c))
 for n,s,k in [('agent','ORCHESTRATION','agent'),('rag','RETRIEVAL','rag'),('graph','KNOWLEDGE','graph'),('eval','LLM QUALITY','eval'),('memory','CONTEXT','memory'),('tool','ACTION','tool')]: (OUT/f'{n}-{suf}.svg').write_text(card(n.upper(),s,c,dark,k))
print('assets generated')
